أَخْبَرَنَا /26 مَكِّيُّ بْنُ إِبْرَاهِيمَ L7660 /26 , أَخْبَرَنَا /26 أَبُو حَنِيفَةَ L1734 /26 , عَنْ /26 عَلْقَمَةَ بْنِ مَرْثَدٍ L5716 /26 , /27 عَنْ /26 عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ L4740 /26 , عَنْ /93 أَبِيهِ L1841 /93 , عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، قَالَ : /20 " نَهَيْنَاكُمْ عَنْ زِيَارَةِ الْقُبُورِ , فَزُورُوهَا وَلا تَقُولُوا هُجْرًا , وَعَنْ لُحُومِ الأَضَاحِي أَنْ تَمْسِكُوهَا مَا بَدَا لَكُمْ , وَتَزَوَّدُوا , فَإِنَّا إِنَّمَا نَهَيْنَاكُمْ لِيَتَّسِعَ مُوسِعُكُمْ عَلَى فَقِيرِكُمْ , وَعَنِ النَّبِيذِ فِي وَالدُّبَّاءِ الْحَنْتَمِ , وَالْمُزَفَّتِ , فَاشْرَبُوا فِي كُلِّ ظَرْفٍ وَلا تَشْرَبُوا مُسْكِرًا " /27 . أَخْبَرَنَا /94 أَحْمَدُ بْنُ مُحَمَّدٍ الْهَمْدَانِيُّ L10300 /94 , أَخْبَرَنَا /26 الْعَبَّاسُ بْنُ السِّنْدِيِّ الأَنْطَاكِيُّ L20257 /26 , /26 وَمُحَمَّدُ بْنُ إِسْمَاعِيلَ بْنِ يُوسُفَ L6823 /26 , قَالا : أَخْبَرَنَا /26 عَبْدُ اللَّهِ بْنُ صَالِحٍ L4864 /26 , حَدَّثَنِي /26 اللَّيْثُ بْنُ سَعْدٍ L6641 /26 , قَالَ الْعَبَّاسُ , عَنْ /26 أَبِي عَبْدِ اللَّهِ الْخُرَاسَانِيِّ L914 /26 , وَقَالَ مُحَمَّدُ بْنُ إِسْمَاعِيلَ , عَنْ /26 أَبِي عَبْدِ الرَّحْمَنِ الْخُرَاسَانِيِّ L914 /26 , عَنْ /26 أَبِي حَنِيفَةَ L1734 /26 , عَنْ /26 عَلْقَمَةَ بْنِ مَرْثَدٍ L5716 /26 , /26 وَحَمَّادٍ L2483 /26 , عَنْ /26 عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ L4740 /26 , عَنْ /93 أَبِيهِ L1841 /93 , عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِثْلَهُ . أَخْبَرَنَا /94 أَحْمَدُ بْنُ مُحَمَّدِ بْنِ سَعِيدٍ L10300 /94 , أَخْبَرَنَا /26 أَحْمَدُ بْنُ حَازِمٍ L9799 /26 , أَخْبَرَنَا /26 عُبَيْدُ اللَّهِ بْنُ مُوسَى L5437 /26 , عَنْ /26 أَبِي حَنِيفَةَ L1734 /26 , عَنْ /26 عَلْقَمَةَ بْنِ مَرْثَدٍ L5716 /26 , عَنِ /26 ابْنِ بُرَيْدَةَ L4740 /26 , عَنْ /93 أَبِيهِ L1841 /93 , عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ : " نَهَيْنَاكُمْ عَنْ ثَلاثٍ عَنْ زِيَارَةِ الْقُبُورِ " . فَذَكَرَ الْحَدِيثَ بِطُولِهِ . قَالَ الشَّيْخُ : وَقَدْ رَوَى هَذَا الْخَبَرَ , عَنْ أَبِي حَنِيفَةَ جَمَاعَةٌ مِنْهُمْ أَبُو مُعَاذٍ , وَأَبُو مُطِيعٍ الْبَلْخِيَّانِ , وَالنَّضْرُ بْنُ مُحَمَّدٍ الْمَرْوَزِيُّ , وَإِسْمَاعِيلُ بْنُ يَحْيَى الصَّارِفِيُّ , وَالْحَسَنُ بْنُ الْفُرَاتِ , وَمُحَمَّدُ بْنُ مَسْرُوقٍ , وَحَمَّادُ بْنُ أَبِي حَنِيفَةَ , وَأَبُو يُوسُفَ , وَأَسَدُ بْنُ عَمْرٍو , وَالْحَسَنُ بْنُ زِيَادٍ , وَمُحَمَّدُ بْنُ الْحَسَنِ , وَسَعِيدُ بْنُ أَبِي الْجَهْمِ , وَأَيُّوبُ بْنُ هَانِئٍ , وَإِبْرَاهِيمُ , وَالْمُقْرِئُ . فَأَمَّا حَدِيثُ أَبِي مُطِيعٍ : فَحَدَّثَنَا /94 أَبُو عَلِيٍّ الْحَافِظُ عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ يَحْيَى L23104 /94 , أَخْبَرَنَا /26 يَحْيَى بْنُ مُوسَى L8342 /26 , أَخْبَرَنَا /26 أَبُو مُطِيعٍ L15577 /26 , أَخْبَرَنَا /26 أَبُو حَنِيفَةَ L1734 /26 . وَأَمَّا حَدِيثُ أَبِي مُعَاذٍ : فَحَدَّثَنَا /94 أَبُو عَلِيٍّ الْحَافِظُ L23104 /94 , أَخْبَرَنَا /26 يَحْيَى بْنُ مُوسَى L8342 /26 , أَخْبَرَنَا /26 أَبُو مُعَاذٍ L26475 /26 , أَخْبَرَنَا /26 أَبُو حَنِيفَةَ L1734 /26 , إِلا أَنَّهُ قَالَ : " وَلا تَقُولُوا هُجْرًا " . وَأَمَّا حَدِيثُ النَّضْرِ بْنِ مُحَمَّدٍ : فَحَدَّثَنَا /94 مُحَمَّدُ بْنُ عَلِيٍّ سَاوِي الرُّخِّيُّ L30133 /94 , أَخْبَرَنَا /26 حَامِدُ بْنُ آدَمَ L14293 /26 , أَخْبَرَنَا /26 النَّضْرُ بْنُ مُحَمَّدٍ L1725 /26 , أَخْبَرَنَا /26 أَبُو حَنِيفَةَ L1734 /26 . وَأَمَّا حَدِيثُ إِسْمَاعِيلَ بْنِ يَحْيَى الصَّارِفِيُّ , فَكَانَ فِيهِ عَنْ أَبِي حَنِيفَةَ . وَأَمَّا حَدِيثُ الْحَسَنِ بْنِ الْفُرَاتِ : فَأَخْبَرَنَا /94 أَحْمَدُ بْنُ مُحَمَّدٍ L10300 /94 , حَدَّثَنِي /26 الْحَسَنُ بْنُ عَلِيٍّ L1283/26 , قَالَ : هَذَا كِتَابُ الْحَسَنِ بْنِ عَلِيٍّ , فَقَرَأْتُ فِيهِ , أَخْبَرَنَا /26 يَحْيَى بْنُ حُسَيْنٍ L43163 /26 , أَخْبَرَنَا /26 زِيَادٌ L3069 /26 , عَنْ /26 أَبِيهِ L1255 /26 , عَنْ /26 أَبِي حَنِيفَةَ L1734 /26 . وَأَمَّا حَدِيثُ مُحَمَّدِ بْنِ مَسْرُوقٍ :   فَأَخْبَرَنَا /94 أَحْمَدُ بْنُ مُحَمَّدٍ L10300 /94 , أَخْبَرَنِي /94 مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الْمَسْرُوقِيُّ L29753 /94 , قِرَاءَةً قَالَ : وَجَدْتُ فِي كِتَابِ /26 جَدِّي L30651 /26 , أَخْبَرَنَا /26 أَبُو حَنِيفَةَ L1734 /26 . وَأَمَّا حَدِيثُ حَمَّادِ بْنِ أَبِي حَنِيفَةَ : فَحَدَّثَنَا /94 صَالِحُ بْنُ سَعِيدِ بْنِ مِرْدَاسٍ التِّرْمِذِيُّ L79952 /94 , أَخْبَرَنَا /26 صَالِحُ بْنُ مُحَمَّدٍ L19509 /26 , أَخْبَرَنَا /26 حَمَّادُ بْنُ أَبِي حَنِيفَةَ L15667 /26 . وَأَخْبَرَنَا /94 أَحْمَدُ بْنُ مُحَمَّدٍ L10300 /94 , حَدَّثَنِي /26 عَبْدُ اللَّهِ بْنُ أَحْمَدَ بْنِ بُهْلُولٍ L22959 /26 , قَالَ : هَذَا كِتَابُ /26 جَدِّي L12401 /26 , فَقَرَأْتُ فِيهِ ، حَدَّثَنِي /26 أَبِي L15667 /26 , عَنْ /26 أَبِي حَنِيفَةَ L1734 /26 , /26 وَمِسْعَرٍ L7433 /26 , عَنْ /26 عَلْقَمَةَ بْنِ مَرْثَدٍ L5716 /26 . وَأَمَّا حَدِيثُ أَبِي يُوسُفَ : فَأَخبرنا /94 مُحَمَّدُ بْنُ الْحُسَيْنِ الْبَزَّارُ L72293 /94 , أَنْبَأنَا /26 بِشْرُ بْنُ الْوَلِيدِ L12759 /26 , أَنْبَأنَا /26 أَبُو يُوسُفَ L34174 /26 . وَأَخْبَرَنَا /94 أَحْمَدُ بْنُ مُحَمَّدٍ L10300 /94 , قَالَ : أَخْبَرَنِي /26 مُنْذِرُ بْنُ مُحَمَّدٍ L32116 /26 , أَخْبَرَنَا /26 حُسَيْنُ بْنُ مُحَمَّدٍ L59132/26 , أَخْبَرَنَا /26 أَبُو يُوسُفَ L34174 /26 , عَنْ /26 أَبِي حَنِيفَةَ L1734 /26 . وَأَمَّا حَدِيثُ أَسَدِ بْنِ عَمْرٍو : أَخْبَرَنَا /94 أَحْمَدُ بْنُ مُحَمَّدٍ L10300/94 , حَدَّثَنِي /26 مُنْذِرُ بْنُ مُحَمَّدٍ L32116 /26 , حَدَّثَنِي /26 الْحُسَيْنُ بْنُ مُحَمَّدٍ L59132/26 , حَدَّثَنَا /26 أَسَدُ بْنُ عَمْرٍو L10869 /26 , عَنْ /26 أَبِي حَنِيفَةَ L1734 /26 . وَأَمَّا حَدِيثُ الْحَسَنِ بْنِ زِيَادٍ : فَحَدَّثَنَا /94 سَهْلُ بْنُ بِشْرٍ الْكِنْدِيُّ L79932 /94 , أَخْبَرَنَا /26 الْفَتْحُ بْنُ عَمْرٍو L26359 /26 , أَنْبَأنَا /26 الْحَسَنُ بْنُ زِيَادٍ L14859 /26 . وأَخْبَرَنَا /94 أَحْمَدُ بْنُ مُحَمَّدٍ L10300/94 , أَخْبَرَنَا /26 مُنْذِرُ بْنُ مُحَمَّدٍ L32116 /26 , حَدَّثَنِي /26 أَبِي L53399/26 , حَدَّثَنَا /26 الْحَسَنُ بْنُ زِيَادٍ L14859 /26 , عَنْ /26 أَبِي حَنِيفَة L1734 /26 . وَأَمَّا حَدِيثُ مُحَمَّدِ بْنِ الْحَسَنِ : فحَدَّثَنَا /94 مُحَمَّدُ بْنُ رِضْوَانَ L79917 /94 ، أَخْبَرَنَا /26 مُحَمَّدُ بْنُ سَلامٍ L6995 /26 , أَنْبَأنَا /26 مُحَمَّدُ بْنُ الْحَسَنِ L27627 /26 , عَنْ /26 أَبِي حَنِيفَةَ L1734 /26 . وَأَمَّا حَدِيثُ سَعِيدِ بْنِ أَبِي الْجَهْمِ : فَأَخْبَرَنِي /94 أَحْمَدُ بْنُ مُحَمَّدٍ L10300/94 , أَخْبَرَنِي /26 الْمُنْذِرُ بْنُ مُحَمَّدٍ L32116 /26 , حَدَّثَنِي /26 أَبِي L53399/26 , حَدَّثَنِي /26 عَمِّي L36085/26 , عَنْ /26 أَبِي حَنِيفَةَ L1734 /26 . وَأَمَّا حَدِيثُ أَيُّوبَ بْنِ هَانِئٍ : فَأَنْبَا /94 أَحْمَدُ بْنُ مُحَمَّدٍ L10300/94 , أَخْبَرَنِي /26 مُنْذِرُ بْنُ مُحَمَّدٍ L32116 /26 , حَدَّثَنِي /26 أَبِي L53399/26 , أَخْبَرَنَا /26 أَيُّوبُ بْنُ هَانِئٍ L11174 /26 , عَنْ /26 أَبِي حَنِيفَةَ L1734 /26 . وَأَمَّا حَدِيثُ إِبْرَاهِيمَ : فَأَخْبَرَنَا /94 أَحْمَدُ بْنُ مُحَمَّدٍ L10300 /94 , قَالَ : أَخْبَرَنِي /26 حَسَنُ بْنُ عُمَرَ بْنِ إِبْرَاهِيمَ L15359 /26 , أَخْبَرَنَا /26 أَبِي L40188 /26 , أَخْبَرَنَا /26 أَبُو حَنِيفَةَ L1734 /26 . وَأَمَّا حَدِيثُ الْمُقْرِئِ : فَحَدَّثَنَا /94 عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَلِيٍّ الْبَلْخِيُّ L23104 /94 , أَخْبَرَنَا /26 عَبْدُ اللَّهِ بْنُ أَحْمَدَ الْمَكِّيُّ L21819 /26 , أَخْبَرَنَا /26 الْمُقْرِئُ L5157 /26 , أَخْبَرَنَا /26 أَبُو حَنِيفَةَ L1734 /26 * 
